-- Hosbah (MH-580 J6): one row per hostname Hosbah TLS-dials on the team's behalf — every app domain
-- and proxy host whose tls is 'auto' (an 'internal' or 'off' hostname carries no public
-- certificate worth watching). source is 'app' (internal/db's domains table) or 'proxy'
-- (proxy_hosts); the hostname is also unique across both there, so (team_id, hostname) is unique
-- here too. The sweep (internal/certcheck) TLS-dials the hostname, records issuer, the validity
-- window and whether the hostname is covered by the certificate's SANs (san_match), and clears or
-- sets error. alerted_14/7/1/alerted_failure dedupe notifications: each is set once its threshold
-- fires and reset together whenever not_after changes (a renewal) or the check starts passing
-- again, so the same expiry or the same failure is not announced twice. Rows go with their team;
-- nothing here is written in plain team scope (Scope{System: true, TeamID: ...}), like server_metrics.
ALTER TABLE ssl_certificates ADD CONSTRAINT ssl_certificates_source_check CHECK (source IN ('app', 'proxy'));
ALTER TABLE ssl_certificates ADD CONSTRAINT ssl_certificates_hostname_check CHECK (length(hostname) <= 253);
CREATE UNIQUE INDEX ssl_certificates_team_hostname_key ON ssl_certificates (team_id, hostname);
CREATE INDEX ssl_certificates_team_idx ON ssl_certificates (team_id);
CREATE INDEX ssl_certificates_not_after_idx ON ssl_certificates (not_after);
